    next(new Error('Unauthorized'));
  }
}

function andRestrictTo(role) {
  return function(req, res, next) {
    if (req.authenticatedUser.role == role) {
      next();
    } else {
      next(new Error('Unauthorized'));
    }
  }
}

function next(err) {
  if (err === 'route') {
    err = undefined;
  }

  var layer = stack[idx++];
  if (!layer) {
    return done(err);
  }

  if (slashAdded) {
    req.url = req.url.substr(1);
    slashAdded = false;
  }

  req.url = protohost + removed + req.url.substr(protohost.length);
  req.originalUrl = req.originalUrl || req.url;
  removed = '';

  try {
    var path = parseUrl(req).pathname;
    if (undefined == path) path = '/';

    if (!layer.match(path)) return next(err);

    // route object and not middleware
    var route = layer.route;

    // if final route, then we support options
    if (route) {
      // we don't run any routes with error first
      if (err) {
        return next(err);
      }

      req.route = route;

      // we can now dispatch to the route
      if (method === 'options' && !route.methods['options']) {
        options.push.apply(options, route._options());
      }
    }

    req.params = layer.params;

    // this should be done for the layer
    return self.process_params(layer, req, res, function(err) {
      if (err) {
        return next(err);
      }

      if (route) {
        return layer.handle(req, res, next);
      }

      trim_prefix();
    });

  } catch (err) {
    next(err);
  }

function wrap(old, fn) {
  return function () {
    var args = [old].concat(slice.call(arguments));
    fn.apply(this, args);
  };
}

